function drawEnemies(){const scale=mapRect.w/DESIGN.w,ts=performance.now();for(const e of state.enemies){if(!Number.isFinite(e.x)||!Number.isFinite(e.y))continue;const size=(e.kind==='superiorBoss'?138:e.kind==='boss'?116:e.kind==='ram'||e.kind==='catapult'?76:e.kind==='large'?66:52)*scale;drawEnemySprite(e,size,ts);if(!e.dead){const w=size*.78;ctx.fillStyle='rgba(0,0,0,.72)';ctx.fillRect(e.x-w/2,e.y-size*.98,w,6);let ratio=clamp(e.hp/e.maxHp,0,1);if(isSuperiorBossKind(e.kind)){const totalLives=e.maxLives||2;const livesLeft=(e.extraLives||0)+ratio;ratio=clamp(livesLeft/totalLives,0,1);ctx.fillStyle='#6e3bb1';ctx.fillRect(e.x-w/2,e.y-size*.98,w,6);ctx.fillStyle='#c98bff';ctx.fillRect(e.x-w/2,e.y-size*.98,w*ratio,6);ctx.strokeStyle='rgba(255,255,255,.55)';ctx.beginPath();ctx.moveTo(e.x,e.y-size*.98);ctx.lineTo(e.x,e.y-size*.98+6);ctx.stroke();continue}ctx.fillStyle=isBossKind(e.kind)?'#ff9d43':e.phase==='attack'?'#ffb54a':'#ff5f6f';ctx.fillRect(e.x-w/2,e.y-size*.98,w*ratio,6)}}}
